#!/usr/bin/env python3
"""Build a sourced artist profile, shared by home and its dedicated page."""
import json,re
from pathlib import Path
from html import escape as e
ROOT=Path(__file__).resolve().parents[1]/'classic'
sources=[
 {'id':'rostros','title':'Iconos Pop · Naroa sobre el retrato','url':'https://naroagutierrez.wordpress.com/2020/09/27/iconos-pop-muestra-colectiva-de-retratos/','supports':'Atracción por los rostros y cita sobre reconocerse en los demás.'},
 {'id':'materiales','title':'Madera, Papel y Tijera','url':'https://naroagutierrez.wordpress.com/2017/04/02/madera-papel-y-tijera-en-ambigu/','supports':'Experimentación con soportes, collage y elementos reciclados.'},
 {'id':'recreo','title':'El ReCreo · Espacio de creación','url':'https://naroagutierrez.wordpress.com/2024/01/12/el-recreo-espacio-de-creacion-para-recrearte/','supports':'Acompañamiento respetuoso y juego creativo multigeneracional; se presenta como proyecto documentado en 2024, sin anunciar horarios actuales.'},
 {'id':'autorretrato','title':'Autorretratos: Mujeres a través del Espejo','url':'https://naroagutierrez.wordpress.com/2026/05/14/autorretratos-mujeres-a-traves-del-espejo/','supports':'Taller cursado en 2025 con Ana Rosa Arroyo; Rara Avis, pastel y collage; imagen original de 4080 × 3072.'},
 {'id':'walking','title':'Walking Gallery · Por Amor al Arte','url':'https://naroagutierrez.wordpress.com/2022/10/04/walking-gallery-bilbao-octubre-2022-por-amor-al-arte/','supports':'Convocatoria de Naroa para compartir creaciones en las calles de Bilbao.'},
 {'id':'pizarra','title':'DiviNos VaiVenes','url':'https://naroagutierrez.wordpress.com/2026/01/15/divinos-vaivenes-muestra-plastica-en-politena-espacio-de-arte/','supports':'Pizarra, mica y retrato; Vaivenes y reutilización de materiales.'},
 {'id':'retrato','title':'Espejos del Alma · Archivo de la artista','url':'https://naroagutierrez.wordpress.com/2015/05/24/espejos-del-alma-en-el-colegio-de-abogados-de-bilbao/','supports':'Retrato con chistera y monóculo, imagen original de 2201 × 3468; identidad del fotógrafo no confirmada.'},
 {'id':'prensa','title':'Colonias de Arte de Portugalete · 2024','url':'https://www.enportugalete.com/articulo/actualidad/colonias-arte-portugalete-volveran-centrarse-sostenibilidad/20240515102022016891.html','supports':'Faceta de acompañamiento creativo y coordinación de Walking Gallery en Bilbao.'}
]
def source(id,label):
 s=next(s for s in sources if s['id']==id)
 return f'<a href="{e(s["url"])}" target="_blank" rel="noopener noreferrer">{label} ↗</a>'
body=f'''<div class="artist-profile">
<header class="artist-hero"><img src="/images/sobre-mi/naroa-monoculo.jpg" width="2201" height="3468" alt="Naroa Gutiérrez Gil con chistera, sosteniendo un monóculo ante un ojo" loading="lazy" decoding="async"><div class="artist-hero__shade"></div><div class="artist-hero__text"><p class="artist-kicker">Sobre mí · Artista plástica · Bilbao</p><h2 id="artist-title">Naroa<br><span>Gutiérrez Gil</span></h2><p>Rostros, materia<br>y ganas de jugar.</p></div></header>
<p class="artist-caption">Retrato de Naroa · Archivo de la artista, publicado en 2015. {source('retrato','Ver publicación')}</p>
<div class="artist-opening"><p class="artist-kicker">Mirar a los demás.<br>Encontrarse en ellos.</p><div><p class="artist-lead">Naroa Gutiérrez Gil trabaja con rostros. Los dibuja, los pinta y los reconstruye con papeles, texturas y objetos. En cada retrato hay también una pregunta por quien lo mira.</p><p>En sus textos, crear y conocerse aparecen una y otra vez de la mano. Las figuras del cine, la música o la televisión son el punto de partida para hablar de emociones, de identidad y de aquello que reconocemos en otras personas.</p></div></div>
<figure class="artist-quote"><blockquote>«Me encontré a mí en los demás».</blockquote><figcaption>Naroa Gutiérrez Gil · {source('rostros','Iconos Pop, 2020')}</figcaption></figure>
<section class="artist-chapter" aria-labelledby="artist-materials"><p class="artist-kicker">01 · La materia</p><div><h3 id="artist-materials">Lo que cuenta<br>cada material.</h3><p>Una pizarra, un plato de madera, un recorte o una lata pueden convertirse en parte del retrato. El soporte aporta significado: la pintura convive con las huellas, las capas y las posibilidades de cada objeto.</p><p>En <em>Vaivenes</em>, el collage y los materiales reutilizados dan forma a vivencias y estados de ánimo. En <em>DiviNos</em>, los rostros sobre pizarra incorporan pintura, lápices de colores y mica. Experimentar con lo que tiene entre manos es parte de su manera de encontrar nuevas imágenes.</p><div class="artist-links">{source('materiales','Madera, Papel y Tijera')}{source('pizarra','DiviNos VaiVenes')}</div></div></section>
<figure class="artist-wide"><a href="/obra/amor-en-conserva/" aria-label="Descubrir Amor en Conserva"><img src="/images/catalogo/amor-en-conserva-hq-01.jpg" width="2048" height="1536" alt="Amor en Conserva: composición de retratos en una lata abierta" loading="lazy" decoding="async"></a><figcaption><span>Amor en Conserva · Retrato, fotografía y objeto.</span><a href="/obra/amor-en-conserva/">Descubrir la obra →</a></figcaption></figure>
<section class="artist-chapter" aria-labelledby="artist-self"><p class="artist-kicker">02 · La propia mirada</p><div><h3 id="artist-self">También al otro<br>lado del espejo.</h3><p>Después de años retratando a otras personas, Naroa cuenta que dibujarse directamente ante un espejo supuso un reto nuevo. En 2025 participó en el taller de autorretrato de Ana Rosa Arroyo, en la asociación Mujeres en la Diversidad.</p><p><em>Rara Avis</em> reúne esa exploración en un autorretrato de pastel y collage. La imagen se rodea de marcos, reflejos, papeles y una pluma de pavo real. Mirarse se convierte, otra vez, en una oportunidad para experimentar.</p><div class="artist-links">{source('autorretrato','Leer cómo nació Rara Avis')}</div></div></section>
<figure class="artist-wide"><a href="/obra/rara-avis/" aria-label="Descubrir Rara Avis"><img src="/images/sobre-mi/rara-avis.jpg" width="4080" height="3072" alt="Rara Avis: autorretrato de Naroa integrado en un collage con marcos, papeles y una pluma" loading="lazy" decoding="async"></a><figcaption><span>Rara Avis · Pastel y collage · Imagen publicada en 2026.</span><a href="/obra/rara-avis/">Descubrir la obra →</a></figcaption></figure>
<section class="artist-chapter" aria-labelledby="artist-share"><p class="artist-kicker">03 · Compartir</p><div><h3 id="artist-share">Crear también<br>es encontrarse.</h3><p>Su relación con el arte se extiende a los espacios compartidos. En Bilbao, sus convocatorias de <em>Walking Gallery</em> invitan a sacar las creaciones a la calle y conversar mientras se camina con ellas.</p><p>En 2024 presentó <em>El ReCreo</em>, un espacio de experimentación para personas de distintas edades. Cada participante podía escoger qué hacer y a qué ritmo, con el acompañamiento que necesitara. La curiosidad, el respeto y el disfrute del proceso atraviesan esta otra faceta de su práctica.</p><div class="artist-links">{source('walking','Walking Gallery')}{source('recreo','Conocer El ReCreo')}</div><a class="artist-trajectory" href="/trayectoria/">Recorrer su trayectoria →</a></div></section>
<section class="artist-notebook" id="about-journal" aria-labelledby="artist-notebook-title"><p class="artist-kicker">Cuaderno de estudio</p><h3 id="artist-notebook-title">Contado por Naroa.</h3><p>En su blog escribe sobre las obras, las personas y los procesos que las acompañan. Un lugar para acercarse a su voz y a su manera de mirar.</p><a href="https://naroagutierrez.wordpress.com/" target="_blank" rel="noopener noreferrer">Leer el cuaderno →</a></section>
<div class="artist-contact"><p>Un rostro.<br>Una historia por contar.</p><a href="mailto:naroa@naroa.eu">Hablar con Naroa ↗</a><a href="/#/destacada">Explorar la obra →</a></div></div>'''
# Read actual image dimensions rather than assuming the format of the catalogue file.
