index=(ROOT/'index.html').read_text()
pattern=r'<section id="view-about"[\s\S]*?(?=<!-- ═══ SECTION: EXPOSICIONES)'
assert len(re.findall(pattern,index))==1
index=re.sub(pattern,lambda _:f'<section id="view-about" class="view view--about view--premium-dark" aria-labelledby="artist-title">{body}</section>\n\n    ',index,count=1)
index=index.replace('href="#/about" class="nav__link"','href="/sobre-mi/" class="nav__link"')
